from pathlib import Path
import re

p=Path('lib/main.dart')
text=p.read_text(encoding='utf-8')
original=text

# Convert loading-state no-op callbacks into true disabled callbacks.
text=re.sub(r"loading\s*\?\s*\(\)\s*\{\s*\}\s*:\s*onRefresh","loading ? null : onRefresh",text)
text=re.sub(r"loading\s*\?\s*\(\)\s*\{\s*\}\s*:\s*([A-Za-z_]\w*)",r"loading ? null : \1",text)
text=re.sub(r"onPressed\s*:\s*\(\)\s*\{\s*\}\s*,","onPressed:null,",text)
text=re.sub(r"onTap\s*:\s*\(\)\s*\{\s*\}\s*,","onTap:null,",text)

# Repair the premium header ternary generated by the page-accent layer.
text=text.replace('desktop?.07:.18','desktop ? .07 : .18')
text=text.replace('desktop?.16:.34','desktop ? .16 : .34')

# Merge the existing map cleanup with the new weather-animation timer cleanup.
old_dispose="""  @override
  void dispose(){
    _radarRefreshTimer?.cancel();
    _viewportRefreshTimer?.cancel();
    super.dispose();
  }

  @override
  void dispose(){_radarAnimationTimer?.cancel();super.dispose();}
"""
new_dispose="""  @override
  void dispose(){
    _radarRefreshTimer?.cancel();
    _viewportRefreshTimer?.cancel();
    _radarAnimationTimer?.cancel();
    super.dispose();
  }
"""
if old_dispose in text:
    text=text.replace(old_dispose,new_dispose,1)
else:
    text=text.replace('  @override\n  void dispose(){_radarAnimationTimer?.cancel();super.dispose();}\n\n','',1)
    map_start=text.find('class _IntelligenceMapPageState')
    map_end=text.find('class _MapLegendDot',map_start)
    map_block=text[map_start:map_end]
    if '_radarAnimationTimer?.cancel();' not in map_block:
        map_block=map_block.replace('    _viewportRefreshTimer?.cancel();\n    super.dispose();','    _viewportRefreshTimer?.cancel();\n    _radarAnimationTimer?.cancel();\n    super.dispose();',1)
        text=text[:map_start]+map_block+text[map_end:]

# Only the shared _IconButton should accept null for a disabled state.
icon_start=text.find('class _IconButton extends StatelessWidget')
if icon_start<0: raise SystemExit('_IconButton class missing')
icon_end=text.find('\n}',icon_start)
if icon_end<0: raise SystemExit('_IconButton class end missing')
icon_block=text[icon_start:icon_end]
icon_block=icon_block.replace('final VoidCallback onTap;','final VoidCallback? onTap;')
icon_block=icon_block.replace('child: Icon(icon, color: AppTheme.textMuted, size: 20),','child: Icon(icon, color: onTap==null?Colors.white24:AppTheme.textMuted, size: 20),')
text=text[:icon_start]+icon_block+text[icon_end:]

# Verify the known release breakpoints are gone.
if re.search(r"on(?:Pressed|Tap)\s*:\s*\(\)\s*\{\s*\}",text): raise SystemExit('an empty click handler remains after cleanup')
for bad in ['desktop?.07:.18','desktop?.16:.34','void dispose(){_radarAnimationTimer?.cancel();super.dispose();}']:
    if bad in text: raise SystemExit(f'combined compile issue remains: {bad}')
icon_check=text[icon_start:text.find('\n}',icon_start)]
if 'final VoidCallback? onTap;' not in icon_check: raise SystemExit('_IconButton callback is still non-nullable')
if text==original: raise SystemExit('No dead click/compile changes applied')
p.write_text(text,encoding='utf-8')
print('Replaced no-op click handlers and repaired combined release compile breakpoints v194b')
